async function handleAuthFormSubmit(e) {
    e.preventDefault();
    const email = document.getElementById("authEmailInput").value.trim();
    const password = document.getElementById("authPasswordInput").value.trim();

    if (authModalMode === "login") {
        try {
            const res = await fetch("/api/auth/login", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ email, password })
            });
            const data = await res.json();
            if (data.success) {
                currentUser = data.user;
                updateUserInterfaceForRole();
                document.getElementById("authModal").classList.add("hidden");
                alert("લૉગ ઇન સફળ થયું!");
            } else {
                alert(data.message || "ખોટી વિગતો છે.");
            }
        } catch (err) {
            alert("ક્ષતિ: " + err);
        }
    } else {
        const name = document.getElementById("authNameInput").value.trim();
        const firm = document.getElementById("authFirmInput").value.trim();
        const regNo = document.getElementById("authRegNumberInput").value.trim();

        try {
            const res = await fetch("/api/auth/register", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    name,
                    email,
                    password,
                    role: selectedRoleInModal,
                    company_or_firm_name: firm,
                    membership_or_gstin: regNo
                })
            });
            const data = await res.json();
            if (data.success) {
                currentUser = data.user;
                updateUserInterfaceForRole();
                document.getElementById("authModal").classList.add("hidden");
                alert("રજીસ્ટ્રેશન સફળ થયું!");
            } else {
                alert(data.message || "ક્ષતિ આવી.");
            }
        } catch (err) {
            alert("ક્ષતિ: " + err);
        }
    }
}

// ================= DATA LOADING =================

async function loadAllData() {
    let txns = null;
    let stmts = null;

    try {
        const [txnsRes, stmtsRes] = await Promise.all([
            fetch(`/api/transactions?country=${currentCountry}`),
            fetch(`/api/financial-statements?country=${currentCountry}`)
        ]);
        if (txnsRes.ok && stmtsRes.ok) {
            txns = await txnsRes.json();
            stmts = await stmtsRes.json();
        }
    } catch (err) {
        // Standalone / Netlify / Offline mode
    }

    if (!txns || !stmts) {
        txns = DynamicLocalStore.getTransactions(currentCountry);
        stmts = DynamicLocalStore.generateStatements(currentCountry);
    }

    lastTransactionsList = txns;
    lastFullStatements = stmts;
    lastFinancialPnl = stmts.profit_and_loss;

    updateKPIs(stmts);
    renderRecentTransactions(txns);
    renderTransactionsTable(txns);
    renderTrialBalance(stmts.trial_balance);
    renderFinancialChart(stmts.profit_and_loss, stmts);
    renderExpensePieChart(stmts.profit_and_loss ? stmts.profit_and_loss.expenses : []);
    renderCashFlowLineChart(txns, stmts.profit_and_loss);
    renderBalanceSheetChart(stmts.balance_sheet);
    renderFinancialReports(stmts);
    refreshTaxData();
    loadCAClients();
    loadERPCockpitStats();
}

function updateKPIs(stmts) {
    const pnl = stmts.profit_and_loss || {};
    const rev = pnl.total_revenue || 0;
    const exp = pnl.total_expenses || 0;
    const profit = pnl.net_profit || 0;
    const margin = pnl.net_profit_margin_percent || 0;

    document.getElementById("kpiRevenue").textContent = `${currencySymbol}${rev.toLocaleString()}`;
    document.getElementById("kpiExpenses").textContent = `${currencySymbol}${exp.toLocaleString()}`;
    document.getElementById("kpiNetProfit").textContent = `${currencySymbol}${profit.toLocaleString()}`;
    document.getElementById("kpiProfitMargin").textContent = `${margin}% Profit Margin`;

    let taxDue = profit * 0.05;
    document.getElementById("kpiTaxDue").textContent = `${currencySymbol}${Math.round(taxDue).toLocaleString()}`;
}

function renderRecentTransactions(txns) {
    const list = document.getElementById("recentTxnsList");
    list.innerHTML = "";
    const recent = [...txns].reverse().slice(0, 5);

    recent.forEach(t => {
        const item = document.createElement("div");
        item.className = "p-2.5 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-between text-xs";
        item.innerHTML = `
            <div>
                <p class="font-bold text-slate-200">${t.description}</p>
                <p class="text-[10px] text-slate-400">${t.date} • ${t.reference_no}</p>
            </div>
            <div class="text-right">
                <p class="font-mono font-bold text-white">${currencySymbol}${Number(t.amount).toLocaleString()}</p>
                <span class="text-[9px] px-1.5 py-0.2 rounded bg-slate-800 text-emerald-400 font-mono">${t.category || 'General'}</span>
            </div>
        `;
        list.appendChild(item);
    });
}

function renderTransactionsTable(txns) {
    const tbody = document.getElementById("transactionsTableBody");
    tbody.innerHTML = "";

    txns.forEach(t => {
        const tr = document.createElement("tr");
        tr.className = "hover:bg-slate-900/50 transition";
        tr.innerHTML = `
            <td class="p-3 text-slate-400 font-mono text-[11px]">${t.date}</td>
            <td class="p-3 font-semibold text-slate-200 font-mono">${t.reference_no}</td>
            <td class="p-3">${t.description}</td>
            <td class="p-3 text-emerald-400 font-semibold">${t.debit_account}</td>
            <td class="p-3 text-amber-400 font-semibold">${t.credit_account}</td>
            <td class="p-3 text-right font-mono font-bold text-white">${currencySymbol}${Number(t.amount).toLocaleString()}</td>
            <td class="p-3 text-right font-mono text-slate-400">${currencySymbol}${Number(t.tax_amount || 0).toLocaleString()}</td>
            <td class="p-3 text-center">
                <button onclick="deleteTransaction('${t.id}')" class="text-rose-400 hover:text-rose-300 p-1">
                    <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                </button>
            </td>
        `;
        tbody.appendChild(tr);
    });
    lucide.createIcons();
}

function renderTrialBalance(tb) {
    if (!tb) return;
    document.getElementById("tbTotalDebit").textContent = `${currencySymbol}${Number(tb.total_debit).toLocaleString()}`;
    document.getElementById("tbTotalCredit").textContent = `${currencySymbol}${Number(tb.total_credit).toLocaleString()}`;
    const statusEl = document.getElementById("trialBalanceStatus");
    const dict = I18N[currentLang] || I18N["en"];
    statusEl.textContent = tb.is_balanced ? dict.tb_balanced : "Variance Detected";
}

// ================= CA VISUAL ANALYTICS & MULTI-CHART SUITE =================

function setupChartControls() {
    // 1. Chart Type Switchers (Bar, Pie, Doughnut, Line, Polar)
    const typeButtons = {
        chartTypeBarBtn: 'bar',
        chartTypePieBtn: 'pie',
        chartTypeDoughnutBtn: 'doughnut',
        chartTypeLineBtn: 'line',
        chartTypePolarBtn: 'polarArea'
    };

    Object.entries(typeButtons).forEach(([btnId, type]) => {
        const btn = document.getElementById(btnId);
        if (btn) {
            btn.addEventListener("click", () => {
                currentChartType = type;
                document.querySelectorAll(".chart-type-btn").forEach(b => {
                    b.classList.remove("active", "bg-amber-500/30", "border-amber-500/50", "text-white");
                    b.classList.add("text-slate-400");
                });
                btn.classList.add("active", "bg-amber-500/30", "border-amber-500/50", "text-white");
                btn.classList.remove("text-slate-400");
                renderFinancialChart(lastFinancialPnl, lastFullStatements);
            });
        }
    });

    // 2. Metric Pills (P&L, Expenses, Balance Sheet)
    const metricButtons = {
        metricPnlBtn: 'pnl',
        metricExpensesBtn: 'expenses',
        metricBalanceSheetBtn: 'balancesheet'
    };

    Object.entries(metricButtons).forEach(([btnId, metric]) => {
        const btn = document.getElementById(btnId);
        if (btn) {
            btn.addEventListener("click", () => {
                currentChartMetric = metric;
                document.querySelectorAll(".metric-pill-btn").forEach(b => {
                    b.classList.remove("active", "bg-amber-500/20", "text-amber-400", "font-bold");
                    b.classList.add("text-slate-400");
                });
                btn.classList.add("active", "bg-amber-500/20", "text-amber-400", "font-bold");
                btn.classList.remove("text-slate-400");
                renderFinancialChart(lastFinancialPnl, lastFullStatements);
            });
        }
    });

    // 3. Export Chart as HD Image for Audit Presentation
    const downloadBtn = document.getElementById("downloadChartImgBtn");
    if (downloadBtn) {
        downloadBtn.addEventListener("click", () => {
            const canvas = document.getElementById("financialChart");
            if (!canvas) return;
            try {
                const imgUrl = canvas.toDataURL("image/png", 1.0);
                const a = document.createElement("a");
                a.href = imgUrl;
                a.download = `Sri_Sri_CA_Analytics_${currentChartMetric}_${currentChartType}_${Date.now()}.png`;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                alert("✅ ચાર્ટ સફળતાપૂર્વક HD PNG ઇમેજ તરીકે ડાઉનલોડ થઈ ગયો છે!");
            } catch (err) {
                alert("ચાર્ટ નિકાસ ક્ષતિ: " + err);
            }
        });
    }
}

function renderFinancialChart(pnl, statements) {
    lastFinancialPnl = pnl;
    if (statements) lastFullStatements = statements;
    const ctx = document.getElementById("financialChart");
    if (!ctx) return;

    if (financialChartInstance) {
        financialChartInstance.destroy();
        financialChartInstance = null;
    }

    const titleEl = document.getElementById("primaryChartTitle");
    const subTitleEl = document.getElementById("primaryChartSubtitle");
    const summaryBadge = document.getElementById("chartTotalSummaryBadge");

    let labels = [];
    let dataValues = [];
    let bgColors = [];
    let borderColors = [];

    const isLight = currentTheme === "purewhite";
    const gridColor = isLight ? 'rgba(226, 232, 240, 0.8)' : 'rgba(212, 175, 55, 0.15)';
    const tickColor = isLight ? '#334e68' : '#cbd5e1';
    const xTickColor = isLight ? '#0c2340' : '#f8fafc';

    if (currentChartMetric === "expenses") {
        if (titleEl) titleEl.textContent = "ખર્ચાઓનું વિસ્તૃત વર્ગીકરણ (Expense Heads)";
        if (subTitleEl) subTitleEl.textContent = "સંચાલકીય અને વહીવટી ખર્ચાઓનું સરખામણી ચિત્ર";
        const expenses = (pnl && pnl.expenses && pnl.expenses.length) ? pnl.expenses : [
            { name: "પગાર અને ભથ્થાં (Salaries)", amount: 180000 },
            { name: "ઓફિસ ભાડું (Office Rent)", amount: 65000 },
            { name: "IT અને ક્લાઉડ સર્વર (Tech Infra)", amount: 45000 },
            { name: "વીજળી & યુટિલિટી (Utilities)", amount: 22000 },
            { name: "ઓડિટ ફી (Audit & Legal)", amount: 35000 },
            { name: "પરચુરણ ખર્ચ (Misc)", amount: 18400 }
        ];
        labels = expenses.map(e => e.name);
        dataValues = expenses.map(e => Number(e.amount) || 0);
        const palette = [
            'rgba(244, 63, 94, 0.85)',
            'rgba(245, 158, 11, 0.85)',
            'rgba(16, 185, 129, 0.85)',
            'rgba(6, 182, 212, 0.85)',
            'rgba(139, 92, 246, 0.85)',
            'rgba(236, 72, 153, 0.85)',
            'rgba(59, 130, 246, 0.85)',
            'rgba(234, 179, 8, 0.85)'
        ];
        bgColors = palette.slice(0, labels.length);
        borderColors = bgColors.map(c => c.replace("0.85", "1.0"));
        const totalExp = dataValues.reduce((a, b) => a + b, 0);
        if (summaryBadge) summaryBadge.textContent = `કુલ ખર્ચ: ${currencySymbol}${totalExp.toLocaleString()}`;
    } else if (currentChartMetric === "balancesheet") {
        if (titleEl) titleEl.textContent = "સંપત્તિ vs જવાબદારીઓ vs મૂડી (Balance Sheet)";
        if (subTitleEl) subTitleEl.textContent = "નાણાકીય સ્થિરતા, એસેટ બેકિંગ અને ઇક્વિટી ગુણોત્તર";
        const bs = (statements && statements.balance_sheet) ? statements.balance_sheet : (lastFullStatements ? lastFullStatements.balance_sheet : {});
        const assets = bs.total_assets || 850000;
        const liab = bs.total_liabilities || 320000;
        const eq = bs.total_equity || 530000;
        labels = currentLang === "en" ? ['Total Assets', 'Total Liabilities', "Owner's Equity"] :
                 (currentLang === "hi" ? ['कुल संपत्ति', 'कुल देयताएं', 'शेयरधारक इक्विटी'] : ['કુલ સંપત્તિ', 'કુલ જવાબદારીઓ', 'માલિકી મૂડી']);
        dataValues = [assets, liab, eq];
        bgColors = [
            'rgba(16, 185, 129, 0.85)',
            'rgba(244, 63, 94, 0.85)',
            'rgba(245, 158, 11, 0.85)'
        ];
        borderColors = ['#10b981', '#f43f5e', '#f59e0b'];
        if (summaryBadge) summaryBadge.textContent = `કુલ સંપત્તિ: ${currencySymbol}${Number(assets).toLocaleString()}`;
    } else {
        // Default P&L
        if (titleEl) titleEl.textContent = "નાણાકીય પ્રવાહ અને નફાકારકતા (P&L Overview)";
        if (subTitleEl) subTitleEl.textContent = "આવક, ખર્ચ અને ચોખ્ખા નફાનું વાસ્તવિક ગ્રાફિકલ ચિત્ર";
        const rev = pnl ? pnl.total_revenue || 0 : 570000;
        const exp = pnl ? pnl.total_expenses || 0 : 430400;
        const net = pnl ? pnl.net_profit || 0 : 139600;
        labels = currentLang === "en" ? ['Revenue', 'Expenses', 'Net Profit'] :
                 (currentLang === "hi" ? ['कुल आय', 'कुल खर्च', 'शुद्ध लाभ'] : ['કુલ આવક', 'કુલ ખર્ચ', 'ચોખ્ખો નફો']);
        dataValues = [rev, exp, net];
        bgColors = [
            'rgba(16, 185, 129, 0.85)',
            'rgba(244, 63, 94, 0.85)',
            'rgba(245, 158, 11, 0.85)'
        ];
        borderColors = ['#10b981', '#f43f5e', '#f59e0b'];
        if (summaryBadge) summaryBadge.textContent = `કુલ આવક: ${currencySymbol}${Number(rev).toLocaleString()} • નફો: ${currencySymbol}${Number(net).toLocaleString()}`;
    }

    const isCartesian = ['bar', 'line'].includes(currentChartType);

    financialChartInstance = new Chart(ctx, {
        type: currentChartType,
        data: {
            labels: labels,
            datasets: [{
                label: 'રકમ',
                data: dataValues,
                backgroundColor: currentChartType === 'line' ? 'rgba(16, 185, 129, 0.25)' : bgColors,
                borderColor: currentChartType === 'line' ? '#10b981' : borderColors,
                borderWidth: 2,
                borderRadius: currentChartType === 'bar' ? 8 : 0,
                fill: currentChartType === 'line',
                tension: 0.35,
                pointBackgroundColor: borderColors,
                pointBorderColor: '#ffffff',
                pointRadius: currentChartType === 'line' ? 5 : 0
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    display: !isCartesian,
                    position: 'bottom',
                    labels: {
                        color: tickColor,
                        font: { size: 11, family: 'Inter, system-ui, sans-serif' },
                        boxWidth: 12
                    }
                },
                tooltip: {
                    backgroundColor: 'rgba(7, 22, 44, 0.95)',
                    titleColor: '#d4af37',
                    bodyColor: '#f8fafc',
                    borderColor: 'rgba(212, 175, 55, 0.4)',
                    borderWidth: 1,
                    padding: 10,
                    callbacks: {
                        label: function(context) {
                            const val = context.parsed.y !== undefined ? context.parsed.y : (context.parsed !== undefined ? context.parsed : context.raw);
                            const total = dataValues.reduce((a, b) => a + b, 0);
                            const pct = total > 0 ? ((val / total) * 100).toFixed(1) : 0;
                            return ` રકમ: ${currencySymbol}${Number(val).toLocaleString()} (${pct}%)`;
                        }
                    }
                }
            },
            scales: isCartesian ? {
                y: {
                    beginAtZero: true,
                    grid: { color: gridColor },
                    ticks: {
                        color: tickColor,
                        font: { size: 10 },
                        callback: val => currencySymbol + Number(val).toLocaleString()
                    }
                },
                x: {
                    grid: { display: false },
                    ticks: { color: xTickColor, font: { size: 11, weight: 'bold' } }
                }
            } : {}
        }
    });
}

function renderExpensePieChart(expenses) {
    const ctx = document.getElementById("expensePieChart");
    if (!ctx) return;

    if (expensePieChartInstance) {
        expensePieChartInstance.destroy();
        expensePieChartInstance = null;
    }

    const sampleExpenses = [
        { name: "પગાર અને ભથ્થાં (Salaries)", amount: 180000 },
        { name: "ઓફિસ ભાડું (Rent)", amount: 65000 },
        { name: "ટેકનોલોજી & ક્લાઉડ (IT)", amount: 45000 },
        { name: "ઓડિટ & લીગલ (Audit Fees)", amount: 35000 },
        { name: "વિજળી & યુટિલિટી (Utilities)", amount: 22000 },
        { name: "મુસાફરી (Conveyance)", amount: 18400 }
    ];

    const expList = (expenses && expenses.length) ? expenses : sampleExpenses;
    const sorted = [...expList].sort((a, b) => b.amount - a.amount);
    const labels = sorted.map(e => e.name);
    const dataVals = sorted.map(e => Number(e.amount) || 0);
    const total = dataVals.reduce((a, b) => a + b, 0);

    const topLbl = document.getElementById("topExpenseHeadLbl");
    const totalLbl = document.getElementById("totalExpensePieLbl");
    if (topLbl && sorted.length) topLbl.textContent = `${sorted[0].name}`;
    if (totalLbl) totalLbl.textContent = `${currencySymbol}${total.toLocaleString()}`;

    const palette = [
        '#f43f5e', '#f59e0b', '#10b981', '#06b6d4',
        '#8b5cf6', '#ec4899', '#3b82f6', '#eab308'
    ];

    const isLight = currentTheme === "purewhite";
    const tickColor = isLight ? '#334e68' : '#cbd5e1';

    expensePieChartInstance = new Chart(ctx, {
        type: 'pie',
        data: {
            labels: labels,
            datasets: [{
                data: dataVals,
                backgroundColor: palette.slice(0, labels.length),
                borderColor: isLight ? '#ffffff' : '#07162c',
                borderWidth: 2
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    display: true,
                    position: 'bottom',
                    labels: {
                        color: tickColor,
                        font: { size: 10, family: 'Inter, system-ui, sans-serif' },
                        boxWidth: 10,
                        padding: 8
                    }
                },
                tooltip: {
                    backgroundColor: 'rgba(7, 22, 44, 0.95)',
                    titleColor: '#d4af37',
                    bodyColor: '#f8fafc',
                    borderColor: 'rgba(212, 175, 55, 0.4)',
                    borderWidth: 1,
                    padding: 8,
                    callbacks: {
                        label: function(ctx) {
                            const val = ctx.raw || 0;
                            const pct = total > 0 ? ((val / total) * 100).toFixed(1) : 0;
                            return ` ${ctx.label}: ${currencySymbol}${Number(val).toLocaleString()} (${pct}%)`;
                        }
                    }
                }
            }
        }
    });
}

function renderGstDoughnutChart(tax) {
    const ctx = document.getElementById("gstDoughnutChart");
    if (!ctx) return;

    if (gstDoughnutChartInstance) {
        gstDoughnutChartInstance.destroy();
        gstDoughnutChartInstance = null;
    }

    const gst = (tax && tax.gst) ? tax.gst : {
        output_gst_collected: 36000,
        input_tax_credit_available: 30600,
        net_gst_payable_cash: 5400,
        itc_carried_forward: 0
    };

    const output = Number(gst.output_gst_collected) || 36000;
    const itc = Number(gst.input_tax_credit_available) || 30600;
    const cash = Number(gst.net_gst_payable_cash) || 5400;
    const carry = Number(gst.itc_carried_forward) || 0;

    const itcRatioBadge = document.getElementById("itcRatioBadge");
    const netTaxCashLbl = document.getElementById("netTaxCashPieLbl");
    if (netTaxCashLbl) netTaxCashLbl.textContent = `${currencySymbol}${cash.toLocaleString()}`;
    if (itcRatioBadge && output > 0) {
        const ratio = ((itc / output) * 100).toFixed(1);
        itcRatioBadge.textContent = `${ratio}% ITC ક્રેડિટ મેળવેલ`;
    }

    const labels = [
        'વેચાણ પર આઉટપુટ GST',
        'માન્ય ઇનપુટ ક્રેડિટ (ITC)',
        'નેટ કેશ ભરવાપાત્ર કર',
        'આગળ ખેંચેલ ITC'
    ];
    const dataVals = [output, itc, cash, carry > 0 ? carry : 500];
    const colors = ['#f59e0b', '#06b6d4', '#f43f5e', '#10b981'];

    const isLight = currentTheme === "purewhite";
    const tickColor = isLight ? '#334e68' : '#cbd5e1';

    gstDoughnutChartInstance = new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: labels,
            datasets: [{
                data: dataVals,
                backgroundColor: colors,
                borderColor: isLight ? '#ffffff' : '#07162c',
                borderWidth: 2,
                cutout: '65%'
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    display: true,
                    position: 'bottom',
                    labels: {
                        color: tickColor,
                        font: { size: 10, family: 'Inter, system-ui, sans-serif' },
                        boxWidth: 10,
                        padding: 8
                    }
                },
                tooltip: {
                    backgroundColor: 'rgba(7, 22, 44, 0.95)',
                    titleColor: '#d4af37',
                    bodyColor: '#f8fafc',
                    borderColor: 'rgba(212, 175, 55, 0.4)',
                    borderWidth: 1,
                    padding: 8,
                    callbacks: {
                        label: function(ctx) {
                            return ` ${ctx.label}: ${currencySymbol}${Number(ctx.raw).toLocaleString()}`;
                        }
                    }
                }
            }
        }
    });
}

function renderCashFlowLineChart(txns, pnl) {
    const ctx = document.getElementById("cashFlowLineChart");
    if (!ctx) return;

    if (cashFlowLineChartInstance) {
        cashFlowLineChartInstance.destroy();
        cashFlowLineChartInstance = null;
    }

    const rev = pnl ? pnl.total_revenue || 570000 : 570000;
    const exp = pnl ? pnl.total_expenses || 430400 : 430400;

    const months = ['એપ્રિલ', 'મે', 'જૂન', 'જુલાઈ', 'ઓગસ્ટ', 'સપ્ટેમ્બર'];
    const inflowData = [
        Math.round(rev * 0.12),
        Math.round(rev * 0.15),
        Math.round(rev * 0.17),
        Math.round(rev * 0.16),
        Math.round(rev * 0.20),
        Math.round(rev * 0.20)
    ];
    const outflowData = [
        Math.round(exp * 0.13),
        Math.round(exp * 0.15),
        Math.round(exp * 0.16),
        Math.round(exp * 0.18),
        Math.round(exp * 0.19),
        Math.round(exp * 0.19)
    ];
    const netCashData = inflowData.map((inf, i) => inf - outflowData[i]);

    const isLight = currentTheme === "purewhite";
    const gridColor = isLight ? 'rgba(226, 232, 240, 0.8)' : 'rgba(212, 175, 55, 0.15)';
    const tickColor = isLight ? '#334e68' : '#cbd5e1';

    cashFlowLineChartInstance = new Chart(ctx, {
        type: 'line',
        data: {
            labels: months,
            datasets: [
                {
                    label: 'આવક પ્રવાહ (Inflow)',
                    data: inflowData,
                    borderColor: '#10b981',
                    backgroundColor: 'rgba(16, 185, 129, 0.15)',
                    fill: true,
                    tension: 0.35,
                    borderWidth: 2,
                    pointRadius: 3
                },
                {
                    label: 'ખર્ચ પ્રવાહ (Outflow)',
                    data: outflowData,
                    borderColor: '#f43f5e',
                    backgroundColor: 'rgba(244, 63, 94, 0.10)',
                    fill: true,
                    tension: 0.35,
                    borderWidth: 2,
                    borderDash: [4, 4],
                    pointRadius: 3
                },
                {
                    label: 'નેટ સરપ્લસ (Net Cash)',
                    data: netCashData,
                    borderColor: '#38bdf8',
                    backgroundColor: 'transparent',
                    borderWidth: 2.5,
                    pointRadius: 4,
                    pointBackgroundColor: '#38bdf8'
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    position: 'bottom',
                    labels: {
                        color: tickColor,
                        font: { size: 10, family: 'Inter, system-ui, sans-serif' },
                        boxWidth: 10,
                        padding: 8
                    }
                },
                tooltip: {
                    backgroundColor: 'rgba(7, 22, 44, 0.95)',
                    titleColor: '#d4af37',
                    bodyColor: '#f8fafc',
                    borderColor: 'rgba(212, 175, 55, 0.4)',
                    borderWidth: 1,
                    padding: 8,
                    callbacks: {
                        label: function(ctx) {
                            return ` ${ctx.dataset.label}: ${currencySymbol}${Number(ctx.raw).toLocaleString()}`;
                        }
                    }
                }
            },
            scales: {
                y: {
                    grid: { color: gridColor },
                    ticks: {
                        color: tickColor,
                        font: { size: 9 },
                        callback: val => currencySymbol + Number(val).toLocaleString()
                    }
                },
                x: {
                    grid: { display: false },
                    ticks: { color: tickColor, font: { size: 10 } }
                }
            }
        }
    });
}

function renderBalanceSheetChart(bs) {
    const ctx = document.getElementById("balanceSheetChart");
    if (!ctx) return;

    if (balanceSheetChartInstance) {
        balanceSheetChartInstance.destroy();
        balanceSheetChartInstance = null;
    }

    const data = bs || (lastFullStatements ? lastFullStatements.balance_sheet : {});
    const assets = Number(data.total_assets) || 850000;
    const liab = Number(data.total_liabilities) || 320000;
    const eq = Number(data.total_equity) || 530000;

    const astEl = document.getElementById("bsChartTotalAssetsLbl");
    const liabEl = document.getElementById("bsChartTotalLiabLbl");
    const eqEl = document.getElementById("bsChartTotalEquityLbl");
    if (astEl) astEl.textContent = `${currencySymbol}${assets.toLocaleString()}`;
    if (liabEl) liabEl.textContent = `${currencySymbol}${liab.toLocaleString()}`;
    if (eqEl) eqEl.textContent = `${currencySymbol}${eq.toLocaleString()}`;

    const isLight = currentTheme === "purewhite";
    const tickColor = isLight ? '#334e68' : '#cbd5e1';

    balanceSheetChartInstance = new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: ['કુલ સંપત્તિ (Assets)', 'કુલ જવાબદારીઓ (Liabilities)', 'માલિકની મૂડી (Equity)'],
            datasets: [{
                data: [assets, liab, eq],
                backgroundColor: ['#10b981', '#f43f5e', '#f59e0b'],
                borderColor: isLight ? '#ffffff' : '#07162c',
                borderWidth: 2,
                cutout: '60%'
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    position: 'bottom',
                    labels: {
                        color: tickColor,
                        font: { size: 10, family: 'Inter, system-ui, sans-serif' },
                        boxWidth: 10,
                        padding: 8
                    }
                },
                tooltip: {
                    backgroundColor: 'rgba(7, 22, 44, 0.95)',
                    titleColor: '#d4af37',
                    bodyColor: '#f8fafc',
                    borderColor: 'rgba(212, 175, 55, 0.4)',
                    borderWidth: 1,
                    padding: 8,
                    callbacks: {
                        label: function(ctx) {
                            return ` ${ctx.label}: ${currencySymbol}${Number(ctx.raw).toLocaleString()}`;
                        }
                    }
                }
            }
        }
    });
}

// ================= OCR SCANNER =================

async function uploadInvoiceFile(file) {
    const status = document.getElementById("scanStatus");
    status.classList.remove("hidden");

    const formData = new FormData();
    formData.append("file", file);
    formData.append("country", currentCountry);
    formData.append("is_sample", "false");

    try {
        const res = await fetch("/api/scan-invoice", { method: "POST", body: formData });
        const data = await res.json();
        if (data.success) displayExtractedInvoice(data.extracted_data);
    } catch (err) {
        alert("સ્કેનિંગ ક્ષતિ: " + err);
    } finally {
        status.classList.add("hidden");
    }
}

async function loadSampleInvoice() {
    const status = document.getElementById("scanStatus");
    status.classList.remove("hidden");

    const formData = new FormData();
    formData.append("country", currentCountry);
    formData.append("is_sample", "true");

    try {
        const res = await fetch("/api/scan-invoice", { method: "POST", body: formData });
        const data = await res.json();
        if (data.success) displayExtractedInvoice(data.extracted_data);
    } catch (err) {
        console.error(err);
    } finally {
        status.classList.add("hidden");
    }
}

function displayExtractedInvoice(inv) {
    currentExtractedInvoice = inv;
    const container = document.getElementById("extractedContent");
    const badge = document.getElementById("extractedBadge");
    const postBtn = document.getElementById("postToBooksBtn");

    badge.textContent = "AI Analysis Ready";
    badge.className = "text-[10px] px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 font-bold";
    postBtn.disabled = false;

    let itemsHtml = "";
    (inv.items || []).forEach(it => {
        itemsHtml += `
            <div class="flex justify-between py-1 border-b border-slate-800 text-[11px]">
                <span class="text-slate-300">${it.description} (x${it.quantity})</span>
                <span class="font-mono text-white">${inv.currency} ${Number(it.amount).toLocaleString()}</span>
            </div>
        `;
    });

    const je = inv.suggested_journal_entry || {};

    container.innerHTML = `
        <div class="space-y-3">
            <div class="grid grid-cols-2 gap-2 p-3 bg-slate-900 rounded-xl border border-slate-800">
                <div>
                    <span class="text-slate-500 block text-[10px]">પાર્ટી / Vendor:</span>
                    <span class="font-bold text-white">${inv.party_name}</span>
                </div>
                <div>
                    <span class="text-slate-500 block text-[10px]">Tax ID / GSTIN / VAT:</span>
                    <span class="font-mono text-emerald-400 font-semibold">${inv.party_tax_id || 'N/A'}</span>
                </div>
                <div>
                    <span class="text-slate-500 block text-[10px]">Invoice # & Date:</span>
                    <span class="font-mono text-slate-300">${inv.invoice_number} | ${inv.invoice_date}</span>
                </div>
                <div>
                    <span class="text-slate-500 block text-[10px]">Total Amount:</span>
                    <span class="font-bold text-emerald-400 text-sm font-mono">${inv.currency} ${Number(inv.total_amount).toLocaleString()}</span>
                </div>
            </div>

            <div class="bg-slate-900 p-2.5 rounded-xl border border-slate-800">
                ${itemsHtml || '<p class="text-slate-500">સામાન્ય ખરીદી</p>'}
            </div>

            <div class="p-3 bg-emerald-950/30 rounded-xl border border-emerald-600/30 font-mono text-[11px]">
                <p class="font-bold text-emerald-400 mb-1">Auto Double Entry:</p>
                <div class="flex justify-between text-slate-300">
                    <span>Dr. ${je.debit_account || inv.category}:</span>
                    <span>${inv.currency} ${Number(je.amount || inv.subtotal).toLocaleString()}</span>
                </div>
                ${je.tax_amount > 0 ? `
                <div class="flex justify-between text-teal-300">
                    <span>Dr. Input Tax / VAT / ITC:</span>
                    <span>${inv.currency} ${Number(je.tax_amount).toLocaleString()}</span>
                </div>
                ` : ''}
                <div class="flex justify-between text-amber-400 border-t border-slate-800 pt-1 mt-1">
                    <span>Cr. ${je.credit_account || 'Bank Account'}:</span>
                    <span>${inv.currency} ${Number(inv.total_amount).toLocaleString()}</span>
                </div>
            </div>
        </div>
    `;
}

async function postCurrentInvoiceToBooks() {
    if (!currentExtractedInvoice) return;
    const inv = currentExtractedInvoice;
    const je = inv.suggested_journal_entry || {};

    const entryPayload = {
        date: inv.invoice_date || new Date().toISOString().split("T")[0],
        reference_no: inv.invoice_number || `INV-${Date.now()}`,
        description: `${inv.party_name} - ${inv.category}`,
        debit_account: je.debit_account || inv.category,
        credit_account: je.credit_account || "Bank Account",
        amount: inv.subtotal || inv.total_amount,
        tax_account: je.tax_amount > 0 ? (je.tax_account || "Input Tax Credit / Tax Receivable") : null,
        tax_amount: inv.tax_amount || 0,
        category: inv.category,
        country: currentCountry
    };

    try {
        const res = await fetch("/api/transactions", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(entryPayload)
        });
        const data = await res.json();
        if (data.success) {
            alert("આ બિલની ડબલ-એન્ટ્રી ચોપડામાં સફળતાપૂર્વક થઈ ગઈ છે!");
            currentExtractedInvoice = null;
            document.getElementById("postToBooksBtn").disabled = true;
            document.getElementById("extractedBadge").textContent = "હિસાબમાં નોંધાઈ ગયું ✅";
            loadAllData();
            switchTab("tab-ledger");
        }
    } catch (err) {
        alert("ક્ષતિ: " + err);
    }
}

