let currentActiveClient = {
    id: "CL-001",
    name: "રિલાયન્સ સુપરમાર્કેટ્સ લિ.",
    gstin: "24AAACR1234F1Z5"
};

function switchActiveClient(id, name, gstin, auditStatus) {
    currentActiveClient = { id, name, gstin, auditStatus };
    const vaultNameEl = document.getElementById("activeClientVaultName");
    const vaultGstEl = document.getElementById("activeClientGstin");
    if (vaultNameEl) vaultNameEl.textContent = name;
    if (vaultGstEl) vaultGstEl.textContent = `GSTIN: ${gstin} | આઇસોલેટેડ વોલ્ટ #${id} સક્રિય • ${auditStatus || ''}`;

    alert(`સક્રિય ક્લાયન્ટ વોલ્ટ બદલાઈ ગયો:\n\nકંપની: ${name}\nGSTIN: ${gstin}\nવોલ્ટ ID: #${id}\n\nICAI Code of Ethics મુજબ આ ક્લાયન્ટનો તમામ એકાઉન્ટિંગ અને ટેક્સ ડેટા અન્ય કંપનીઓથી સુરક્ષિત અને આઇસોલેટેડ છે.`);
}

async function signClientAudit(clientId, clientName) {
    const pin = prompt(`કંપની: ${clientName}\n\nકાયદેસર ઓડિટ રિપોર્ટ (Form 3CD / CARO 2020) પર ડિજિટલ સહી કરવા માટે અધિકૃત CA પાર્ટનર PIN (2FA Step-Up) દાખલ કરો:\n(ડિફોલ્ટ સેટ PIN: 7788)`);
    if (!pin) return;

    try {
        const res = await fetch("/api/security/partner-pin", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ pin: pin })
        });
        const result = await res.json();
        if (!result.success) {
            alert("અધિકૃતતા નિષ્ફળ: " + result.message);
            return;
        }

        const udin = "24" + Math.floor(100000 + Math.random() * 900000) + "CA" + Math.floor(1000 + Math.random() * 9000);
        alert(`✅ કાયદેસર ઓડિટ સફળતાપૂર્વક સહી થઈ ગયું!\n\nકંપની: ${clientName}\nજનરેટ થયેલ UDIN: ${udin}\nઓડિટિંગ ધોરણો: MCA Rule 11(g) & ICAI CARO 2020\nબ્લોકચેન હેશ MCA ઓડિટ ટ્રેઇલ લેજરમાં કાયમી નોંધાઈ ગયું છે.`);

        loadCAClients();
        loadMcaAuditBlocks();
    } catch (err) {
        alert("ઓડિટ સહી પ્રક્રિયામાં ક્ષતિ: " + err);
    }
}

async function loadCAClients() {
    let clients = null;
    try {
        const res = await fetch("/api/clients");
        if (res.ok) {
            clients = await res.json();
        }
    } catch (err) {}

    if (!clients) {
        clients = DynamicLocalStore.getClients();
    }
    const tbody = document.getElementById("clientsTableBody");
    if (!tbody) return;

        tbody.innerHTML = "";
        clients.forEach(c => {
            const tr = document.createElement("tr");
            tr.className = "hover:bg-slate-900/50 transition";
            const isSigned = (c.audit_status || "").includes("Signed");
            const panOrGst = (isPiiMaskingActive && c.pan_masked) ? `${c.gstin} (${c.pan_masked})` : c.gstin;
            const cid = c.client_id || c.id || "CL-000";

            tr.innerHTML = `
                <td class="p-3 font-bold text-white">
                    <div>${c.name}</div>
                    <span class="text-[10px] text-slate-400 font-mono">ID: ${cid}</span>
                </td>
                <td class="p-3 font-mono text-emerald-400">${panOrGst}</td>
                <td class="p-3 text-right font-mono font-bold text-white">${c.turnover || '₹0'}</td>
                <td class="p-3 text-slate-300">${c.gstr_status || 'ફાઇલ થયેલ'}</td>
                <td class="p-3 text-emerald-400 font-semibold">${c.itc_mismatch || '₹0'}</td>
                <td class="p-3 text-center">
                    <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold ${isSigned ? 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/30' : 'bg-amber-500/15 text-amber-300 border border-amber-500/30'}">
                        ${c.audit_status || 'પેન્ડિંગ'}
                    </span>
                </td>
                <td class="p-3 text-center">
                    <div class="flex items-center justify-center space-x-1.5">
                        <button class="switch-client-btn px-2.5 py-1 rounded-lg bg-indigo-600/30 hover:bg-indigo-600 text-indigo-300 hover:text-white border border-indigo-500/40 text-[11px] font-bold transition" data-id="${cid}" data-name="${c.name}" data-gstin="${c.gstin}" data-audit="${c.audit_status}">
                            વોલ્ટ ખોલો
                        </button>
                        <button class="sign-audit-btn px-2.5 py-1 rounded-lg ${isSigned ? 'bg-emerald-600/30 text-emerald-300 border border-emerald-500/40' : 'bg-amber-500/20 hover:bg-amber-500 hover:text-slate-950 text-amber-300 border border-amber-500/40'} text-[11px] font-bold transition" data-id="${cid}" data-name="${c.name}">
                            ${isSigned ? '✓ સહી થયેલ' : 'ઓડિટ સાઇન'}
                        </button>
                    </div>
                </td>
            `;
            tbody.appendChild(tr);
        });

        // Attach action handlers
        tbody.querySelectorAll(".switch-client-btn").forEach(btn => {
            btn.addEventListener("click", () => {
                const id = btn.getAttribute("data-id");
                const name = btn.getAttribute("data-name");
                const gstin = btn.getAttribute("data-gstin");
                const audit = btn.getAttribute("data-audit");
                switchActiveClient(id, name, gstin, audit);
            });
        });

        tbody.querySelectorAll(".sign-audit-btn").forEach(btn => {
            btn.addEventListener("click", () => {
                const id = btn.getAttribute("data-id");
                const name = btn.getAttribute("data-name");
                signClientAudit(id, name);
            });
        });
}

function setupDynamicClientsEvents() {
    const openBtn = document.getElementById("openAddClientModalBtn");
    const closeBtn = document.getElementById("closeAddClientModalBtn");
    const modal = document.getElementById("addClientModal");
    const form = document.getElementById("addClientForm");

    if (openBtn && modal) {
        openBtn.addEventListener("click", () => {
            modal.classList.remove("hidden");
        });
    }
    if (closeBtn && modal) {
        closeBtn.addEventListener("click", () => {
            modal.classList.add("hidden");
        });
    }
    if (modal) {
        modal.addEventListener("click", (e) => {
            if (e.target === modal) modal.classList.add("hidden");
        });
    }

    if (form) {
        form.addEventListener("submit", async (e) => {
            e.preventDefault();
            const name = document.getElementById("newClientName")?.value || "";
            const gstin = document.getElementById("newClientGstin")?.value || "";
            const pan = document.getElementById("newClientPan")?.value || "";
            const turnover = document.getElementById("newClientTurnover")?.value || "₹0";
            const bank = document.getElementById("newClientBank")?.value || "";
            const email = document.getElementById("newClientEmail")?.value || "";

            try {
                const res = await fetch("/api/clients", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        name: name,
                        gstin: gstin,
                        pan: pan,
                        turnover: turnover,
                        bank_account: bank,
                        contact_email: email
                    })
                });
                const data = await res.json();
                if (data.success) {
                    alert(`✅ નવો ક્લાયન્ટ "${name}" સફળતાપૂર્વક ઉમેરાઈ ગયો!\n\nવોલ્ટ ID: ${data.client.client_id}\nMCA બ્લોકચેન ઓડિટ ચેઇનમાં રજીસ્ટર થઈ ગયું છે.`);
                    form.reset();
                    if (modal) modal.classList.add("hidden");
                    loadCAClients();
                    loadMcaAuditBlocks();
                } else {
                    alert("ક્લાયન્ટ ઉમેરવામાં ક્ષતિ: " + (data.detail || "અજ્ઞાત ક્ષતિ"));
                }
            } catch (err) {
                alert("સર્વર ક્ષતિ: " + err);
            }
        });
    }
}

