// ================= AI CHAT & NOTICE SOLVER =================

async function handleChatSubmit(e) {
    e.preventDefault();
    const input = document.getElementById("chatInput");
    const msg = input.value.trim();
    if (!msg) return;

    input.value = "";
    appendChatMessage("user", msg);

    try {
        const res = await fetch("/api/chat", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                message: msg,
                conversation_history: chatHistory,
                country: currentCountry,
                language: currentLang
            })
        });
        const data = await res.json();
        appendChatMessage("ai", data.reply);
    } catch (err) {
        appendChatMessage("ai", "ક્ષતિ: સંપર્ક થઈ શક્યો નથી.");
    }
}

function appendChatMessage(role, text) {
    chatHistory.push({ role, content: text });
    const container = document.getElementById("chatMessages");
    const div = document.createElement("div");
    div.className = "flex items-start space-x-2.5";

    if (role === "user") {
        div.className += " justify-end";
        div.innerHTML = `
            <div class="p-3 rounded-2xl bg-emerald-600 text-white max-w-lg leading-relaxed text-xs">
                ${text}
            </div>
            <div class="w-7 h-7 rounded-lg bg-slate-700 text-white flex items-center justify-center text-xs font-bold shrink-0">
                U
            </div>
        `;
    } else {
        div.innerHTML = `
            <img src="logo.png" alt="AI" class="w-7 h-7 rounded-lg object-cover shrink-0">
            <div class="p-3.5 rounded-2xl bg-slate-900 border border-slate-800 max-w-lg text-slate-200 leading-relaxed text-xs whitespace-pre-line shadow-md">
                ${text}
            </div>
        `;
    }
    container.appendChild(div);
    container.scrollTop = container.scrollHeight;
}

function loadSampleNotice() {
    document.getElementById("noticeInputText").value = `INCOME TAX DEPARTMENT - NATIONAL FACELESS ASSESSMENT CENTRE
Notice under Section 143(1)(a) of the Income-tax Act, 1961
PAN: AAACS9981M | Assessment Year: 2026-27

Sub: Mismatch in Form 26AS receipts vs Return filed.
Gross turnover reported in ITR is ₹3,97,000 whereas receipts reflecting in Form 26AS is ₹4,20,000, creating an apparent variance of ₹23,000.
Please show cause within 30 days why adjustment and demand under Section 143(1)(a) should not be made.`;
}

async function analyzeNotice() {
    const text = document.getElementById("noticeInputText").value.trim();
    if (!text) return;

    const resArea = document.getElementById("noticeResultArea");
    resArea.classList.remove("hidden");
    document.getElementById("noticeDraftText").textContent = "AI નોટિસનું કાયદેસર વિશ્લેષણ કરી રહ્યું છે...";

    try {
        const res = await fetch("/api/analyze-notice", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                notice_text: text,
                country: currentCountry,
                language: currentLang
            })
        });
        const data = await res.json();
        document.getElementById("noticeSectionTag").textContent = data.relevant_section || "Section 143(1)";
        document.getElementById("noticeDraftText").textContent = data.formal_draft_reply || data.allegation_summary;
    } catch (err) {
        document.getElementById("noticeDraftText").textContent = "ક્ષતિ: " + err;
    }
}

function copyNoticeReply() {
    const text = document.getElementById("noticeDraftText").textContent;
    navigator.clipboard.writeText(text);
    alert("કાયદેસર પ્રત્યુત્તર પત્ર કોપી થઈ ગયો છે!");
}

async function handleNewEntrySubmit(e) {
    e.preventDefault();
    const payload = {
        date: document.getElementById("entryDate").value,
        reference_no: document.getElementById("entryRef").value,
        description: document.getElementById("entryDesc").value,
        debit_account: document.getElementById("entryDebitAcc").value,
        credit_account: document.getElementById("entryCreditAcc").value,
        amount: parseFloat(document.getElementById("entryAmount").value),
        tax_amount: parseFloat(document.getElementById("entryTaxAmount").value || 0),
        country: currentCountry
    };

    let saved = false;
    try {
        const res = await fetch("/api/transactions", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });
        if (res.ok) {
            const data = await res.json();
            if (data.success) saved = true;
        }
    } catch (err) {}

    if (!saved) {
        DynamicLocalStore.saveTransaction(payload, currentCountry);
        saved = true;
    }

    if (saved) {
        document.getElementById("newEntryModal").classList.add("hidden");
        document.getElementById("newEntryForm").reset();
        alert("✅ નવું વાઉચર સફળતાપૂર્વક પોસ્ટ થઈ ગયું છે! ખાતાવહી, ચાર્ટ્સ અને વાર્ષિક હિસાબો આપોઆપ અપડેટ થયા.");
        loadAllData();
    }
}

async function deleteTransaction(id) {
    if (!confirm("આ વ્યવહાર કાઢી નાખવો છે?")) return;
    try {
        await fetch(`/api/transactions/${id}`, { method: "DELETE" });
    } catch (err) {}
    DynamicLocalStore.deleteTransaction(id, currentCountry);
    loadAllData();
}

// ================= HIGH-TECH ERP SUITE CLIENT LOGIC (BEYOND ODOO & ZOHO) =================
let erpCachedInvoices = [];
let erpCachedEmployees = [];

function setupERPEvents() {
    // 1. Invoicing UI Events
    const openInvBtn = document.getElementById("openNewInvoiceFormBtn");
    const cancelInvBtn = document.getElementById("cancelInvoiceFormBtn");
    const invContainer = document.getElementById("newInvoiceContainer");
    const invForm = document.getElementById("createInvoiceForm");
    const closeInvModal = document.getElementById("closeInvoicePreviewBtn");

    if (openInvBtn && invContainer) {
        openInvBtn.addEventListener("click", () => {
            const today = new Date().toISOString().split("T")[0];
            const dateInput = document.getElementById("invDate");
            if (dateInput) dateInput.value = today;
            invContainer.classList.remove("hidden");
        });
    }
    if (cancelInvBtn && invContainer) {
        cancelInvBtn.addEventListener("click", () => invContainer.classList.add("hidden"));
    }
    if (invForm) {
        invForm.addEventListener("submit", handleCreateInvoice);
    }
    if (closeInvModal) {
        closeInvModal.addEventListener("click", () => {
            const modal = document.getElementById("invoicePreviewModal");
            if (modal) modal.classList.add("hidden");
        });
    }

    // 2. Inventory UI Events
    const openSkuBtn = document.getElementById("openNewSkuBtn");
    const cancelSkuBtn = document.getElementById("cancelSkuBtn");
    const skuContainer = document.getElementById("newSkuContainer");
    const skuForm = document.getElementById("createSkuForm");

    if (openSkuBtn && skuContainer) {
        openSkuBtn.addEventListener("click", () => skuContainer.classList.remove("hidden"));
    }
    if (cancelSkuBtn && skuContainer) {
        cancelSkuBtn.addEventListener("click", () => skuContainer.classList.add("hidden"));
    }
    if (skuForm) {
        skuForm.addEventListener("submit", handleCreateSku);
    }

    // 3. Payroll UI Events
    const openEmpBtn = document.getElementById("openNewEmpBtn");
    const cancelEmpBtn = document.getElementById("cancelEmpBtn");
    const empContainer = document.getElementById("newEmpContainer");
    const empForm = document.getElementById("createEmpForm");
    const closeSlipBtn = document.getElementById("closeSalarySlipBtn");

    if (openEmpBtn && empContainer) {
        openEmpBtn.addEventListener("click", () => empContainer.classList.remove("hidden"));
    }
    if (cancelEmpBtn && empContainer) {
        cancelEmpBtn.addEventListener("click", () => empContainer.classList.add("hidden"));
    }
    if (empForm) {
        empForm.addEventListener("submit", handleCreateEmp);
    }
    if (closeSlipBtn) {
        closeSlipBtn.addEventListener("click", () => {
            const modal = document.getElementById("salarySlipModal");
            if (modal) modal.classList.add("hidden");
        });
    }

    // 4. Anomalies / Forensic Audit Event
    const rerunAuditBtn = document.getElementById("rerunAuditBtn");
    if (rerunAuditBtn) {
        rerunAuditBtn.addEventListener("click", loadERPAnomalies);
    }

    // 5. UDIN Generator Event
    const udinForm = document.getElementById("udinGenForm");
    if (udinForm) {
        udinForm.addEventListener("submit", handleGenerateUDIN);
    }
}

// ---- Live Dashboard ERP Cockpit ----
async function loadERPCockpitStats() {
    let invoices = null, inventory = null, payroll = null, anomalies = null;
    try {
        const [invRes, stockRes, payRes, anomRes] = await Promise.all([
            fetch("/api/erp/invoices"),
            fetch("/api/erp/inventory"),
            fetch("/api/erp/payroll"),
            fetch("/api/erp/anomalies")
        ]);
        if (invRes.ok) invoices = await invRes.json();
        if (stockRes.ok) inventory = await stockRes.json();
        if (payRes.ok) payroll = await payRes.json();
        if (anomRes.ok) anomalies = await anomRes.json();
    } catch (err) {}

    if (!invoices) invoices = DynamicLocalStore.getInvoices();
    if (!inventory) inventory = DynamicLocalStore.getInventory();
    if (!payroll) payroll = DynamicLocalStore.getPayroll();
    if (!anomalies) anomalies = DynamicLocalStore.getAnomalies();

    // Cockpit Card 1: Invoices
    const liveInvEl = document.getElementById("erpLiveInvoicesCount");
    if (liveInvEl) liveInvEl.textContent = `${invoices.length} ઇશ્યૂ થયેલ`;

    // Cockpit Card 2: Stock
    const stockValEl = document.getElementById("erpInventoryValuation");
    if (stockValEl) stockValEl.textContent = `${currencySymbol}${inventory.total_valuation.toLocaleString()}`;
    const stockAlertEl = document.getElementById("erpStockAlertBadge");
    if (stockAlertEl) {
        stockAlertEl.textContent = inventory.low_stock_alerts > 0 
            ? `⚠️ ${inventory.low_stock_alerts} રિઓર્ડર ચેતવણી` 
            : `${inventory.total_skus} સક્રિય SKUs`;
    }

    // Cockpit Card 3: Payroll
    const payNetEl = document.getElementById("erpPayrollNet");
    if (payNetEl) payNetEl.textContent = `${currencySymbol}${payroll.total_net_payable.toLocaleString()}`;

    // Cockpit Card 4: Audit Health
    const auditScoreEl = document.getElementById("erpAuditHealthScore");
    if (auditScoreEl) {
        const score = anomalies.audit_score_percent || 94;
        auditScoreEl.textContent = `${score}% હેલ્થ સ્કોર`;
        auditScoreEl.className = score >= 90 
            ? "text-base font-extrabold text-emerald-400 mt-1 font-mono" 
            : "text-base font-extrabold text-rose-400 mt-1 font-mono";
    }
}

// ================= MODULE 1: INVOICING & E-INVOICE =================
async function loadERPInvoices() {
    let invoices = null;
    try {
        const res = await fetch("/api/erp/invoices");
        if (res.ok) invoices = await res.json();
    } catch (err) {}

    if (!invoices) invoices = DynamicLocalStore.getInvoices();
    erpCachedInvoices = invoices;

    const totalAmt = invoices.reduce((sum, i) => sum + (i.total_amount || 0), 0);
    const totalTax = invoices.reduce((sum, i) => sum + (i.tax_amount || 0), 0);

    const amtEl = document.getElementById("invTotalAmount");
    const taxEl = document.getElementById("invTotalTax");
    const countEl = document.getElementById("invTotalCount");
    if (amtEl) amtEl.textContent = `${currencySymbol}${totalAmt.toLocaleString()}`;
    if (taxEl) taxEl.textContent = `${currencySymbol}${totalTax.toLocaleString()}`;
    if (countEl) countEl.textContent = `${invoices.length} ઇન્વોઇસ ઇશ્યૂ થયેલ`;

    const tbody = document.getElementById("invoicesTableBody");
    if (!tbody) return;
    tbody.innerHTML = "";

    invoices.forEach(inv => {
        const tr = document.createElement("tr");
        tr.className = "hover:bg-slate-900/60 transition";
        const shortIrn = inv.irn ? `${inv.irn.slice(0, 10)}...${inv.irn.slice(-6)}` : "NIC-GEN-IRN";
        const statusClass = inv.status === "Paid" 
            ? "bg-emerald-500/15 text-emerald-400 border-emerald-500/30" 
            : "bg-amber-500/15 text-amber-300 border-amber-500/30";

        tr.innerHTML = `
            <td class="p-3 font-mono font-bold text-white">${inv.id}</td>
            <td class="p-3 font-medium text-slate-200">
                <div>${inv.customer_name}</div>
                <div class="text-[10px] text-slate-400 font-mono">${inv.customer_gstin || "URP"}</div>
            </td>
            <td class="p-3 text-slate-400 font-mono">${inv.date}</td>
            <td class="p-3 text-right font-mono font-bold text-white">${currencySymbol}${inv.total_amount.toLocaleString()}</td>
            <td class="p-3 text-right font-mono text-emerald-400">${currencySymbol}${inv.tax_amount.toLocaleString()}</td>
            <td class="p-3 font-mono text-[10px] text-cyan-400 cursor-pointer" title="${inv.irn}">${shortIrn}</td>
            <td class="p-3 text-center">
                <span class="px-2 py-0.5 rounded-full text-[10px] font-bold border ${statusClass}">
                    ${inv.status}
                </span>
            </td>
            <td class="p-3 text-center">
                <button onclick="openInvoicePreview('${inv.id}')" class="px-2.5 py-1 bg-cyan-600/20 hover:bg-cyan-600/40 text-cyan-300 border border-cyan-500/30 rounded-lg font-bold text-[11px] transition">
                    👁️ બિલ જુઓ
                </button>
            </td>
        `;
        tbody.appendChild(tr);
    });
}

async function handleCreateInvoice(e) {
    e.preventDefault();
    const custName = document.getElementById("invCustomerName").value;
    const custGstin = document.getElementById("invCustomerGstin").value;
    const invDate = document.getElementById("invDate").value;
    const desc = document.getElementById("invItemDesc").value || "કન્સલ્ટિંગ અને ઓડિટ સેવાઓ";
    const hsn = document.getElementById("invItemHsn").value || "998313";
    const qty = parseFloat(document.getElementById("invItemQty").value || 1);
    const rate = parseFloat(document.getElementById("invItemRate").value || 10000);
    const autoPost = document.getElementById("invAutoPost").checked;

    const baseAmt = qty * rate;
    const taxAmt = Math.round(baseAmt * 0.18);
    const totalAmt = baseAmt + taxAmt;

    const newInv = {
        id: `INV-2026-${Math.floor(100 + Math.random() * 900)}`,
        customer_name: custName,
        customer_gstin: custGstin,
        date: invDate,
        currency: "INR",
        items: [{ description: desc, hsn: hsn, qty: qty, rate: rate, tax_rate: 18.0, amount: baseAmt }],
        tax_amount: taxAmt,
        total_amount: totalAmt,
        irn: Array.from({length: 64}, () => Math.floor(Math.random()*16).toString(16)).join(''),
        ack_no: `1126${Math.floor(10000000 + Math.random() * 90000000)}`,
        status: "Paid",
        auto_post_ledger: autoPost
    };

    let serverSaved = false;
    try {
        const res = await fetch("/api/erp/invoices", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(newInv)
        });
        if (res.ok) serverSaved = true;
    } catch (err) {}

    DynamicLocalStore.saveInvoice(newInv);
    if (autoPost) {
        DynamicLocalStore.saveTransaction({
            date: invDate,
            description: `E-Invoice: ${custName} - ${desc}`,
            amount: totalAmt,
            debit_account: "Sundry Debtors (Receivables)",
            credit_account: "Revenue - Sales",
            reference_no: newInv.id
        }, currentCountry);
    }

    document.getElementById("newInvoiceContainer").classList.add("hidden");
    document.getElementById("createInvoiceForm").reset();
    alert(`✅ E-Invoice સફળતાપૂર્વક તૈયાર થયું!\nIRN Hash: ${newInv.irn.slice(0, 24)}...\nખાતાવહી અને સ્ટોકમાં ઓટો-પોસ્ટ થઈ ગયું છે.`);
    loadERPInvoices();
    loadAllData();
}

