// ================= MODULE 2: INVENTORY & STOCK VALUATION =================
async function loadERPInventory() {
    let data = null;
    try {
        const res = await fetch("/api/erp/inventory");
        if (res.ok) data = await res.json();
    } catch (err) {}

    if (!data) data = DynamicLocalStore.getInventory();

    const totalValEl = document.getElementById("stockTotalValuation");
    const totalSkusEl = document.getElementById("stockTotalSkus");
    const reorderEl = document.getElementById("stockReorderCount");

    if (totalValEl) totalValEl.textContent = `${currencySymbol}${(data.total_valuation || 0).toLocaleString()}`;
    if (totalSkusEl) totalSkusEl.textContent = `${data.total_skus || (data.items || []).length} SKUs`;
    if (reorderEl) reorderEl.textContent = `${data.low_stock_alerts || 0} Alerts`;

    const tbody = document.getElementById("inventoryTableBody");
    if (!tbody) return;
    tbody.innerHTML = "";

    (data.items || []).forEach(item => {
        const tr = document.createElement("tr");
        tr.className = "hover:bg-slate-900/60 transition";
        const qty = item.stock_qty || item.qty || 0;
        const reorder = item.reorder_level || 5;
        const isLow = qty <= reorder;
        const statusBadge = isLow
            ? `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-500/15 text-rose-400 border border-rose-500/30">Low Stock (${qty} બાકી)</span>`
            : `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">In Stock</span>`;

        tr.innerHTML = `
            <td class="p-3 font-mono font-bold text-white">${item.id || item.sku}</td>
            <td class="p-3 font-medium text-slate-200">${item.name}</td>
            <td class="p-3 text-slate-400">${item.category}</td>
            <td class="p-3 font-mono text-slate-400">${item.hsn || "9983"}</td>
            <td class="p-3 text-right font-mono font-bold ${isLow ? 'text-rose-400' : 'text-white'}">${qty}</td>
            <td class="p-3 text-right font-mono text-slate-300">₹${(item.unit_cost || 0).toLocaleString()}</td>
            <td class="p-3 text-right font-mono text-slate-300">₹${(item.selling_price || item.unit_cost * 1.25 || 0).toLocaleString()}</td>
            <td class="p-3 text-right font-mono font-bold text-emerald-400">₹${(item.valuation || item.total_val || (qty * item.unit_cost)).toLocaleString()}</td>
            <td class="p-3 text-center">${statusBadge}</td>
        `;
        tbody.appendChild(tr);
    });
}

async function handleCreateSku(e) {
    e.preventDefault();
    const payload = {
        name: document.getElementById("skuName").value,
        category: document.getElementById("skuCategory").value,
        hsn: document.getElementById("skuHsn").value,
        stock_qty: parseInt(document.getElementById("skuQty").value || 0),
        reorder_level: parseInt(document.getElementById("skuReorder").value || 5),
        unit_cost: parseFloat(document.getElementById("skuCost").value || 0),
        selling_price: parseFloat(document.getElementById("skuPrice").value || 0)
    };

    try {
        await fetch("/api/erp/inventory", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });
    } catch (err) {}

    const invData = DynamicLocalStore.getInventory();
    const newSku = {
        id: `SKU-${invData.items.length + 1}`,
        sku: `SKU-${invData.items.length + 1}`,
        name: payload.name,
        category: payload.category,
        hsn: payload.hsn,
        stock_qty: payload.stock_qty,
        qty: payload.stock_qty,
        reorder_level: payload.reorder_level,
        unit_cost: payload.unit_cost,
        selling_price: payload.selling_price,
        valuation: payload.stock_qty * payload.unit_cost,
        total_val: payload.stock_qty * payload.unit_cost
    };
    invData.items.push(newSku);
    invData.total_skus = invData.items.length;
    invData.total_valuation += newSku.valuation;
    localStorage.setItem("sri_sri_inventory", JSON.stringify(invData));

    document.getElementById("newSkuContainer").classList.add("hidden");
    document.getElementById("createSkuForm").reset();
    alert("✅ નવી પ્રોડક્ટ (SKU) સફળતાપૂર્વક ઉમેરાઈ ગઈ!");
    loadERPInventory();
    loadERPCockpitStats();
}

// ================= MODULE 3: PAYROLL & SALARY SLIPS =================
async function loadERPPayroll() {
    try {
        const res = await fetch("/api/erp/payroll");
        const data = await res.json();
        erpCachedEmployees = data.employees;

        const grossEl = document.getElementById("payrollTotalGross");
        const netEl = document.getElementById("payrollTotalNet");
        const dedEl = document.getElementById("payrollTotalDeductions");
        const countEl = document.getElementById("payrollStaffCount");

        if (grossEl) grossEl.textContent = `${currencySymbol}${data.total_gross.toLocaleString()}`;
        if (netEl) netEl.textContent = `${currencySymbol}${data.total_net_payable.toLocaleString()}`;
        if (dedEl) dedEl.textContent = `${currencySymbol}${data.total_statutory_deductions.toLocaleString()}`;
        if (countEl) countEl.textContent = `${data.employee_count} કર્મચારીઓ`;

        const tbody = document.getElementById("payrollTableBody");
        if (!tbody) return;
        tbody.innerHTML = "";

        data.employees.forEach(emp => {
            const tr = document.createElement("tr");
            tr.className = "hover:bg-slate-900/60 transition";
            tr.innerHTML = `
                <td class="p-3 font-mono font-bold text-white">${emp.emp_id}</td>
                <td class="p-3 font-bold text-slate-200">${emp.name}</td>
                <td class="p-3 text-slate-400">${emp.designation}</td>
                <td class="p-3 font-mono text-slate-400">${emp.pan}</td>
                <td class="p-3 text-right font-mono font-bold text-white">₹${emp.gross_salary.toLocaleString()}</td>
                <td class="p-3 text-right font-mono text-amber-300">₹${emp.epf_deduction.toLocaleString()}</td>
                <td class="p-3 text-right font-mono text-slate-300">₹${(emp.pt_deduction + emp.tds_deduction).toLocaleString()}</td>
                <td class="p-3 text-right font-mono font-extrabold text-emerald-400">₹${emp.net_payable.toLocaleString()}</td>
                <td class="p-3 text-center">
                    <button onclick="openSalarySlip('${emp.emp_id}')" class="px-2.5 py-1 bg-emerald-600/20 hover:bg-emerald-600/40 text-emerald-300 border border-emerald-500/30 rounded-lg font-bold text-[11px] transition">
                        📄 સ્લિપ જુઓ
                    </button>
                </td>
            `;
            tbody.appendChild(tr);
        });
    } catch (err) {
        console.error("loadERPPayroll error:", err);
    }
}

async function handleCreateEmp(e) {
    e.preventDefault();
    const payload = {
        name: document.getElementById("empName").value,
        designation: document.getElementById("empDesig").value,
        pan: document.getElementById("empPan").value,
        basic_salary: parseFloat(document.getElementById("empBasic").value || 0),
        hra: parseFloat(document.getElementById("empHra").value || 0),
        allowances: parseFloat(document.getElementById("empAllow").value || 0),
        tds_deduction: parseFloat(document.getElementById("empTds").value || 0)
    };

    try {
        const res = await fetch("/api/erp/payroll", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });
        const data = await res.json();
        if (data.success) {
            document.getElementById("newEmpContainer").classList.add("hidden");
            document.getElementById("createEmpForm").reset();
            alert("✅ કર્મચારી પેરોલ સફળતાપૂર્વક ઉમેરાયો અને ખાતાવહીમાં ઓટો-પોસ્ટ થઈ ગયો!");
            loadERPPayroll();
            loadAllData();
        }
    } catch (err) {
        alert("પેરોલ ક્ષતિ: " + err);
    }
}

